//! Repairs outdated 3DMigoto hash values in an installed mod's INI files.
//!
//! A mod matches the game's draws by writing `hash = <8 hex digits>` on
//! `[TextureOverride...]` sections. When a game patch renumbers a buffer, the
//! value in an old mod no longer matches and that part stops loading. The
//! bundled table (`fixer_hash_map.json`, generated by
//! `scripts/generate-fixer-hash-map.py`) lists the values the current game
//! version replaced.
//!
//! Deliberate limits:
//!
//! * Only `hash = ...` values are rewritten. Upstream ZZZ-Mod-Fixer also adds
//!   missing sections, multiplies sections for equivalent hashes and patches
//!   vertex/index buffers; those steps need upstream's GPL-3.0 section
//!   templates, so they are not bundled here.
//! * A value is only rewritten when the table says it is provably stale. The
//!   generator drops every pair whose old value is still current for *any*
//!   character, because a global merge would otherwise rewrite working mods
//!   (e.g. `ebac056e` is current for most characters but an outdated
//!   Belle-Temple/Wise-Temple value).
//! * `DISABLED*.ini`, `desktop.ini` and files ZZMI ignores are never touched.
//! * Nothing is written when no value matches, and the first write keeps the
//!   original as `<file>.ini.bak` through the shared [`text::backup_once`]
//!   helper.

use std::collections::BTreeMap;
use std::fs;
use std::ops::Range;
use std::path::{Path, PathBuf};
use std::sync::LazyLock;

use serde::{Deserialize, Serialize};

use crate::error::AppResult;
use crate::ini_parser::commands::collect_ini_files;
use crate::ini_parser::text;

const TABLE_JSON: &str = include_str!("fixer_hash_map.json");

#[derive(Debug, Deserialize)]
struct TableFile {
    meta: TableMetaFile,
    renames: BTreeMap<String, String>,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct TableMetaFile {
    target_game_version: String,
    source: String,
    source_url: String,
    source_commit: String,
    generated: String,
    renames: u32,
}

/// Which game version the bundled table targets. Shown in the UI so a stale
/// table is visible rather than silent.
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct FixTableInfo {
    pub target_game_version: String,
    pub source: String,
    pub source_url: String,
    pub source_commit: String,
    pub generated: String,
    pub renames: u32,
}

/// One rewritten line.
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct FixEdit {
    /// 1-based line number in the file.
    pub line: u32,
    pub from: String,
    pub to: String,
}

#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct FixFile {
    pub relative_path: String,
    pub edits: Vec<FixEdit>,
}

#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct FixFailure {
    pub relative_path: String,
    pub message: String,
}

/// Result of a read-only check: what would change, and which files can be
/// restored from an existing `.ini.bak`.
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct FixScan {
    pub folder_name: String,
    pub table: FixTableInfo,
    pub files: Vec<FixFile>,
    pub edits: u32,
    pub backups: Vec<String>,
    pub failures: Vec<FixFailure>,
}

#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct FixApplyResult {
    pub folder_name: String,
    pub table: FixTableInfo,
    pub edits: u32,
    pub written: Vec<String>,
    pub failures: Vec<FixFailure>,
}

#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct FixRestoreResult {
    pub folder_name: String,
    pub restored: Vec<String>,
    pub failures: Vec<FixFailure>,
}

static TABLE: LazyLock<TableFile> = LazyLock::new(|| {
    serde_json::from_str(TABLE_JSON).expect("fixer_hash_map.json ships with the binary and parses")
});

fn info() -> FixTableInfo {
    let meta = &TABLE.meta;
    FixTableInfo {
        target_game_version: meta.target_game_version.clone(),
        source: meta.source.clone(),
        source_url: meta.source_url.clone(),
        source_commit: meta.source_commit.clone(),
        generated: meta.generated.clone(),
        renames: meta.renames,
    }
}

struct PlannedFile {
    relative_path: String,
    absolute_path: PathBuf,
    rewritten: String,
    encoding: text::Encoding,
    edits: Vec<FixEdit>,
}

/// Files ZZMI itself ignores, plus the `.ini.bak` siblings this module creates.
fn is_ignored(name: &str) -> bool {
    let lower = name.to_ascii_lowercase();
    lower == "desktop.ini" || lower.starts_with("disabled")
}

/// Byte range of the value on a `hash = <value>` line.
///
/// Commented lines (`;` / `#`), other keys and non-hex values return `None`, so
/// the caller leaves them exactly as they were.
fn hash_value_span(line: &str) -> Option<Range<usize>> {
    let first = line.trim_start_matches([' ', '\t']).chars().next()?;
    if first == ';' || first == '#' {
        return None;
    }

    let equals = line.find('=')?;
    if !line[..equals].trim().eq_ignore_ascii_case("hash") {
        return None;
    }

    let bytes = line.as_bytes();
    let mut start = equals + 1;
    while start < bytes.len() && (bytes[start] == b' ' || bytes[start] == b'\t') {
        start += 1;
    }
    let mut end = start;
    while end < bytes.len() && bytes[end].is_ascii_hexdigit() {
        end += 1;
    }

    (end > start).then_some(start..end)
}

/// Rewrite `hash` values in `content`, returning the new text and every edit.
/// Line endings, indentation, key casing and trailing comments are preserved.
fn rewrite(content: &str) -> (String, Vec<FixEdit>) {
    let renames = &TABLE.renames;
    let mut output = String::with_capacity(content.len());
    let mut edits = Vec::new();

    for (index, line) in content.split('\n').enumerate() {
        if index > 0 {
            output.push('\n');
        }

        let Some(span) = hash_value_span(line) else {
            output.push_str(line);
            continue;
        };

        let value = &line[span.clone()];
        let Some(target) = renames.get(&value.to_ascii_lowercase()) else {
            output.push_str(line);
            continue;
        };

        output.push_str(&line[..span.start]);
        output.push_str(target);
        output.push_str(&line[span.end..]);
        edits.push(FixEdit {
            line: (index + 1) as u32,
            from: value.to_string(),
            to: target.clone(),
        });
    }

    (output, edits)
}

fn plan_file(relative_path: &str, path: &Path) -> AppResult<Option<PlannedFile>> {
    let (content, encoding) = text::read(path)?;
    let (rewritten, edits) = rewrite(&content);

    if edits.is_empty() {
        return Ok(None);
    }

    Ok(Some(PlannedFile {
        relative_path: relative_path.to_string(),
        absolute_path: path.to_path_buf(),
        rewritten,
        encoding,
        edits,
    }))
}

/// Every INI a mod contributes to the game, with the changes it needs.
fn collect_plans(root: &Path) -> (Vec<PlannedFile>, Vec<String>, Vec<FixFailure>) {
    let mut plans = Vec::new();
    let mut backups = Vec::new();
    let mut failures = Vec::new();

    for (relative_path, path, _size) in collect_ini_files(root) {
        let name = path
            .file_name()
            .map(|name| name.to_string_lossy().to_string())
            .unwrap_or_else(|| relative_path.clone());

        if is_ignored(&name) {
            continue;
        }

        if text::backup_path(&path).exists() {
            backups.push(relative_path.clone());
        }

        match plan_file(&relative_path, &path) {
            Ok(Some(plan)) => plans.push(plan),
            Ok(None) => {}
            Err(error) => failures.push(FixFailure {
                relative_path,
                message: error.to_string(),
            }),
        }
    }

    (plans, backups, failures)
}

fn report_files(plans: &[PlannedFile]) -> Vec<FixFile> {
    plans
        .iter()
        .map(|plan| FixFile {
            relative_path: plan.relative_path.clone(),
            edits: plan.edits.clone(),
        })
        .collect()
}

/// Read-only check. Never writes, never creates a backup.
pub fn scan(folder_name: &str, root: &Path) -> AppResult<FixScan> {
    let (plans, backups, failures) = collect_plans(root);

    Ok(FixScan {
        folder_name: folder_name.to_string(),
        table: info(),
        edits: plans.iter().map(|plan| plan.edits.len() as u32).sum(),
        files: report_files(&plans),
        backups,
        failures,
    })
}

/// Rewrite every matching value. Each changed file keeps its original as
/// `<file>.ini.bak` on the first write; a failure on one file does not abort the
/// others.
pub fn apply(folder_name: &str, root: &Path) -> AppResult<FixApplyResult> {
    let (plans, _backups, mut failures) = collect_plans(root);
    let mut written = Vec::new();
    let mut edits = 0;

    for plan in &plans {
        let result = text::backup_once(&plan.absolute_path).and_then(|_| {
            text::write_atomic(
                &plan.absolute_path,
                &text::encode(&plan.rewritten, plan.encoding),
            )
        });

        match result {
            Ok(()) => {
                edits += plan.edits.len() as u32;
                written.push(plan.relative_path.clone());
            }
            Err(error) => failures.push(FixFailure {
                relative_path: plan.relative_path.clone(),
                message: error.to_string(),
            }),
        }
    }

    log::info!(
        "Hash fixer: {} value(s) rewritten in {} file(s) under {}",
        edits,
        written.len(),
        root.display()
    );

    Ok(FixApplyResult {
        folder_name: folder_name.to_string(),
        table: info(),
        edits,
        written,
        failures,
    })
}

/// Restore every INI that has a `.ini.bak`. File contents that already match the
/// backup are left alone so a no-op restore does not touch timestamps.
pub fn restore_backups(folder_name: &str, root: &Path) -> AppResult<FixRestoreResult> {
    let mut restored = Vec::new();
    let mut failures = Vec::new();

    for (relative_path, path, _size) in collect_ini_files(root) {
        let name = path
            .file_name()
            .map(|name| name.to_string_lossy().to_string())
            .unwrap_or_else(|| relative_path.clone());

        if is_ignored(&name) {
            continue;
        }

        let backup = text::backup_path(&path);
        if !backup.is_file() {
            continue;
        }

        let outcome: AppResult<bool> = (|| {
            let original = fs::read(&backup)?;
            let current = fs::read(&path)?;
            if current == original {
                return Ok(false);
            }
            text::write_atomic(&path, &original)?;
            Ok(true)
        })();

        match outcome {
            Ok(true) => restored.push(relative_path),
            Ok(false) => {}
            Err(error) => {
                failures.push(FixFailure {
                    relative_path,
                    message: error.to_string(),
                });
            }
        }
    }

    log::info!(
        "Hash fixer: restored {} INI(s) under {}",
        restored.len(),
        root.display()
    );

    Ok(FixRestoreResult {
        folder_name: folder_name.to_string(),
        restored,
        failures,
    })
}

#[cfg(test)]
mod tests {
    use std::collections::HashSet;
    use std::time::{SystemTime, UNIX_EPOCH};

    use super::*;

    fn temp_dir() -> PathBuf {
        let unique = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .expect("clock")
            .as_nanos();
        let dir = std::env::temp_dir().join(format!(
            "zzmm-hash-fix-test-{}-{unique}",
            std::process::id()
        ));
        fs::create_dir_all(&dir).expect("create temp dir");
        dir
    }

    /// A real pair from the shipped table, so the tests keep working when the
    /// table is regenerated.
    fn sample_pair() -> (String, String) {
        let (old, new) = TABLE
            .renames
            .iter()
            .next()
            .expect("the bundled table has renames");
        (old.clone(), new.clone())
    }

    fn write(dir: &Path, relative: &str, bytes: &[u8]) -> PathBuf {
        let path = dir.join(relative);
        if let Some(parent) = path.parent() {
            fs::create_dir_all(parent).expect("create parent");
        }
        fs::write(&path, bytes).expect("write fixture");
        path
    }

    #[test]
    fn bundled_table_is_internally_consistent() {
        assert!(TABLE.renames.len() > 400, "the table shrank unexpectedly");

        let targets: HashSet<&String> = TABLE.renames.values().collect();
        for (old, new) in &TABLE.renames {
            assert_eq!(old.len(), 8, "{old} is not a hash");
            assert_eq!(new.len(), 8, "{new} is not a hash");
            assert!(old
                .chars()
                .all(|c| c.is_ascii_hexdigit() && !c.is_ascii_uppercase()));
            assert!(new
                .chars()
                .all(|c| c.is_ascii_hexdigit() && !c.is_ascii_uppercase()));
            assert_ne!(old, new);
            // Round trips would make a second run rewrite the new value again.
            assert!(!targets.contains(old), "ambiguous round trip for {old}");
        }
    }

    #[test]
    fn rewrites_only_the_value_and_preserves_the_rest_of_the_line() {
        let (old, new) = sample_pair();
        let source = format!(
            "; header\r\n[TextureOverrideBody]\r\n  HASH = {old} ; keep this\r\nrun = CommandListBody\r\nHashStuff = {old}\r\n"
        );
        let (rewritten, edits) = rewrite(&source);

        assert_eq!(
            rewritten,
            format!(
                "; header\r\n[TextureOverrideBody]\r\n  HASH = {new} ; keep this\r\nrun = CommandListBody\r\nHashStuff = {old}\r\n"
            )
        );
        assert_eq!(edits.len(), 1);
        assert_eq!(edits[0].line, 3);
        assert_eq!(edits[0].from, old);
        assert_eq!(edits[0].to, new);
    }

    #[test]
    fn ignores_comments_other_keys_and_non_hex_values() {
        let (old, _) = sample_pair();
        let source = format!(
            "; hash = {old}\n# hash = {old}\nrun = {old}\nhashex = {old}\n[TextureOverrideX]\nhash = nothex\nhash =\n"
        );
        let (rewritten, edits) = rewrite(&source);

        assert!(edits.is_empty());
        assert_eq!(rewritten, source);
    }

    #[test]
    fn leaves_values_that_are_still_current_alone() {
        let (_, current) = sample_pair();
        let source = format!("[TextureOverrideBody]\nhash = {current}\n");
        let (rewritten, edits) = rewrite(&source);

        assert!(edits.is_empty());
        assert_eq!(rewritten, source);
    }

    #[test]
    fn scan_never_writes() {
        let root = temp_dir();
        let (old, _) = sample_pair();
        let original = format!("[TextureOverrideBody]\nhash = {old}\n");
        let path = write(&root, "Mod/merged.ini", original.as_bytes());

        let scan = scan("Mod", &root).expect("scan");

        assert_eq!(scan.edits, 1);
        assert_eq!(scan.files.len(), 1);
        assert_eq!(scan.files[0].relative_path, "Mod/merged.ini");
        assert!(scan.failures.is_empty());
        assert_eq!(fs::read(&path).expect("read"), original.as_bytes());
        assert!(!text::backup_path(&path).exists());

        fs::remove_dir_all(&root).ok();
    }

    #[test]
    fn apply_backs_up_once_is_idempotent_and_restore_restores() {
        let root = temp_dir();
        let (old, new) = sample_pair();
        let original =
            format!("[TextureOverrideBody]\r\n  hash = {old}\r\nrun = CommandListBody\r\n");
        let path = write(&root, "Mod/merged.ini", original.as_bytes());

        let applied = apply("Mod", &root).expect("apply");
        assert_eq!(applied.edits, 1);
        assert_eq!(applied.written, vec!["Mod/merged.ini".to_string()]);
        assert!(applied.failures.is_empty());

        let backup = text::backup_path(&path);
        assert_eq!(fs::read(&backup).expect("backup"), original.as_bytes());
        let fixed = fs::read_to_string(&path).expect("fixed");
        assert!(fixed.contains(&format!("  hash = {new}\r\n")));
        assert!(fixed.ends_with("run = CommandListBody\r\n"));

        // A second run has nothing left to do and must not touch the backup.
        let again = apply("Mod", &root).expect("second apply");
        assert_eq!(again.edits, 0);
        assert!(again.written.is_empty());
        assert_eq!(fs::read(&backup).expect("backup"), original.as_bytes());

        let restored = restore_backups("Mod", &root).expect("restore");
        assert_eq!(restored.restored, vec!["Mod/merged.ini".to_string()]);
        assert_eq!(fs::read(&path).expect("restored"), original.as_bytes());

        // Nothing differs now, so a second restore reports no work.
        let again = restore_backups("Mod", &root).expect("second restore");
        assert!(again.restored.is_empty());
        assert!(again.failures.is_empty());

        fs::remove_dir_all(&root).ok();
    }

    #[test]
    fn skips_disabled_variants_and_desktop_ini() {
        let root = temp_dir();
        let (old, _) = sample_pair();
        let source = format!("[TextureOverrideBody]\nhash = {old}\n");

        let disabled = write(&root, "Mod/DISABLED_Variant.ini", source.as_bytes());
        let lower = write(&root, "Mod/disabled_variant.ini", source.as_bytes());
        let desktop = write(&root, "Mod/desktop.ini", source.as_bytes());
        let active = write(&root, "Mod/merged.ini", source.as_bytes());

        let scan = scan("Mod", &root).expect("scan");
        assert_eq!(scan.edits, 1);
        assert_eq!(scan.files[0].relative_path, "Mod/merged.ini");

        apply("Mod", &root).expect("apply");

        for untouched in [&disabled, &lower, &desktop] {
            assert_eq!(fs::read(untouched).expect("read"), source.as_bytes());
            assert!(!text::backup_path(untouched).exists());
        }
        assert_ne!(fs::read(&active).expect("read"), source.as_bytes());

        fs::remove_dir_all(&root).ok();
    }

    #[test]
    fn covers_nested_folders_and_files_without_a_trailing_newline() {
        let root = temp_dir();
        let (old, new) = sample_pair();
        let nested = write(
            &root,
            "Mod/variant/part.ini",
            format!("hash={old}").as_bytes(),
        );

        let applied = apply("Mod", &root).expect("apply");
        assert_eq!(applied.written, vec!["Mod/variant/part.ini".to_string()]);
        assert_eq!(
            fs::read_to_string(&nested).expect("read"),
            format!("hash={new}")
        );

        fs::remove_dir_all(&root).ok();
    }

    #[test]
    fn preserves_utf16le_and_bom_encodings() {
        let root = temp_dir();
        let (old, new) = sample_pair();
        let source = format!("[TextureOverrideBody]\r\nhash = {old}\r\n");

        for (name, encoding) in [
            ("Utf16/part.ini", text::Encoding::Utf16Le),
            ("Bom/part.ini", text::Encoding::Utf8Bom),
        ] {
            let path = write(&root, name, &text::encode(&source, encoding));
            apply("Mod", &root).expect("apply");

            let (decoded, detected) = text::decode(&fs::read(&path).expect("read"));
            assert_eq!(detected, encoding);
            assert!(
                decoded.contains(&format!("hash = {new}\r\n")),
                "{name} was not rewritten: {decoded:?}"
            );
        }

        fs::remove_dir_all(&root).ok();
    }

    #[test]
    fn reports_an_untouched_mod_as_clean() {
        let root = temp_dir();
        write(
            &root,
            "Mod/merged.ini",
            b"; nothing to do here\n[TextureOverrideBody]\nhash = 00000000\n",
        );

        let scan = scan("Mod", &root).expect("scan");
        assert_eq!(scan.edits, 0);
        assert!(scan.files.is_empty());
        assert!(scan.backups.is_empty());

        fs::remove_dir_all(&root).ok();
    }

    /// The real `Ming Chen Jane` mod: four hair sections written before game
    /// 2.8, with the 2048p values the database lists for 3.1. Pinning them keeps
    /// a table regeneration from silently dropping a fix that is known to work
    /// against a real mod.
    #[test]
    fn repairs_the_jane_hair_sections_from_a_real_mod() {
        let root = temp_dir();
        let original = "\
; Merged Mod: .\\JaneMod.01\\Jane.ini
[TextureOverrideJaneHairPosition]
hash = e7a3b7dc
run = CommandListJaneHairPosition

[TextureOverrideJaneHairTexcoord]
hash = acec29f8
run = CommandListJaneHairTexcoord

[TextureOverrideJaneHairVertexLimitRaise]
hash = 2d06e785
run = CommandListJaneHairVertexLimitRaise

[TextureOverrideJaneHairIB]
hash = 9268a5af
run = CommandListJaneHairIB
";
        let path = write(&root, "Ming Chen Jane/merged.ini", original.as_bytes());

        let scan = scan("Ming Chen Jane", &root).expect("scan");
        assert_eq!(scan.edits, 4);
        assert_eq!(scan.files.len(), 1);

        apply("Ming Chen Jane", &root).expect("apply");
        let fixed = fs::read_to_string(&path).expect("read");
        for (from, to) in [
            ("e7a3b7dc", "33a09cfe"),
            ("acec29f8", "fa617c9a"),
            ("2d06e785", "74bc0b7f"),
            ("9268a5af", "3275b812"),
        ] {
            assert!(!fixed.contains(from), "{from} survived the fix");
            assert!(fixed.contains(to), "{to} was not written");
        }

        // Everything that is not a hash value stays byte-identical.
        let stripped = |text: &str| {
            let mut out = text.to_string();
            for value in [
                "e7a3b7dc", "33a09cfe", "acec29f8", "fa617c9a", "2d06e785", "74bc0b7f", "9268a5af",
                "3275b812",
            ] {
                out = out.replace(value, "HASH");
            }
            out
        };
        assert_eq!(stripped(&fixed), stripped(original));
        assert_eq!(
            fs::read(text::backup_path(&path)).expect("backup"),
            original.as_bytes()
        );

        fs::remove_dir_all(&root).ok();
    }
}
